## Implementation

### Middleware Protection

To protect API routes:

```typescript
// middleware.ts (Next.js API)
import { NextResponse } from 'next/server';
import { getSession } from '@/lib/auth';
import { checkApiPermission } from '@/lib/api-permissions';

const protectedEndpoints: Record<string, string[]> = {
  'POST /api/worlds': ['user', 'creator', 'editor', 'admin'],
  'PUT /api/worlds/*': ['creator', 'editor', 'admin'],
  'DELETE /api/worlds/*': ['admin'],
  'GET /api/admin/*': ['admin'],
};

export async function middleware(request: NextRequest) {
  const session = await getSession(request);
  const path = request.nextUrl.pathname;
  const method = request.method;
  const key = `${method} ${path}`;

  for (const [pattern, allowedRoles] of Object.entries(protectedEndpoints)) {
    if (matchPattern(pattern, key)) {
      if (!session) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
      }
      if (!allowedRoles.includes(session.user.role)) {
        return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
      }
    }
  }

  return NextResponse.next();
}

function matchPattern(pattern: string, actual: string): boolean {
  const regex = new RegExp('^' + pattern.replace(/\*/g, '.*') + '$');
  return regex.test(actual);
}
```

