### Dynamic Permission Checks

```typescript
// lib/rbac.ts
export async function checkApiAccess(
  user: User,
  endpoint: string,
  method: string,
  resourceOwnerId?: number
): Promise<boolean> {
  // Admin bypass
  if (user.role === 'admin') return true;

  const allowed = await hasRoleEndpointAccess(user.role, endpoint, method);
  if (!allowed) return false;

  // If conditional, check ownership
  if (allowed === 'conditional' && resourceOwnerId) {
    return resourceOwnerId === user.id;
  }

  return true;
}
```

